import { test, expect } from '@playwright/test';

test.describe('Table Row Selection with Header Checkbox', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body><table><thead><tr><th><input type="checkbox" id="selectAll" /></th><th>Name</th><th>Email</th></tr></thead><tbody><tr><td><input type="checkbox" class="rowCheckbox" /></td><td>John Doe</td><td>john@example.com</td></tr><tr><td><input type="checkbox" class="rowCheckbox" /></td><td>Jane Smith</td><td>jane@example.com</td></tr><tr><td><input type="checkbox" class="rowCheckbox" /></td><td>Bob Johnson</td><td>bob@example.com</td></tr></tbody></table><script>document.getElementById("selectAll").addEventListener("change", function() { const checkboxes = document.querySelectorAll(".rowCheckbox"); checkboxes.forEach(cb => cb.checked = this.checked); });</script></body></html>');
  });

  test('should select all rows when header checkbox is clicked', async ({ page }) => {
    const headerCheckbox = page.locator('#selectAll');
    const rowCheckboxes = page.locator('.rowCheckbox');

    await expect(rowCheckboxes).toHaveCount(3);

    for (const checkbox of await rowCheckboxes.all()) {
      await expect(checkbox).not.toBeChecked();
    }

    await headerCheckbox.click();

    for (const checkbox of await rowCheckboxes.all()) {
      await expect(checkbox).toBeChecked();
    }
  });

  test('should deselect all rows when header checkbox is unchecked', async ({ page }) => {
    const headerCheckbox = page.locator('#selectAll');
    const rowCheckboxes = page.locator('.rowCheckbox');

    await headerCheckbox.click();

    for (const checkbox of await rowCheckboxes.all()) {
      await expect(checkbox).toBeChecked();
    }

    await headerCheckbox.click();

    for (const checkbox of await rowCheckboxes.all()) {
      await expect(checkbox).not.toBeChecked();
    }
  });

  test('should maintain header checkbox state when all rows are selected', async ({ page }) => {
    const headerCheckbox = page.locator('#selectAll');
    const rowCheckboxes = page.locator('.rowCheckbox');

    await headerCheckbox.click();

    await expect(headerCheckbox).toBeChecked();

    const allCheckboxes = await rowCheckboxes.all();
    for (const checkbox of allCheckboxes) {
      await expect(checkbox).toBeChecked();
    }
  });
});
